impl AntiRejectOrthogonallyFrom<AntiCircleRotor> for DualNum {
    type Output = VersorEven;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        4       10        0        0
    //    simd3        1        6        0      N/A
    //    simd4        5        6        0      N/A
    // Totals...
    // yes simd       10       22        0      N/A
    //  no simd       27       52        0        0
    fn anti_reject_orthogonally_from(self, other: AntiCircleRotor) -> Self::Output {
        use crate::elements::*;
        let wedge_g0_xyz = Simd32x3::from(self[e5]) * other.group0();
        let wedge_g0_w = other[scalar] * self[e12345];
        let wedge_g1 = Simd32x4::from(self[e5]) * other.group1().xyz().with_w(other[scalar]);
        let right_anti_dual_g2 = other.group2() * Simd32x4::from([-1.0, -1.0, -1.0, 1.0]);
        VersorEven::from_groups(
            // e423, e431, e412, e12345
            Simd32x4::from(wedge_g0_w) * (other.group0() * Simd32x3::from(-1.0)).with_w(right_anti_dual_g2[3]),
            // e415, e425, e435, e321
            ((wedge_g0_xyz * Simd32x3::from(right_anti_dual_g2[3])) - (Simd32x3::from(wedge_g0_w) * other.group1().xyz())).with_w(wedge_g0_w * other[e45]),
            // e235, e315, e125, e5
            (right_anti_dual_g2 * Simd32x3::from(wedge_g0_w).with_w(wedge_g1[3]))
                + (wedge_g1.xyzx() * Simd32x3::from(right_anti_dual_g2[3]).with_w(other[e23]))
                + Simd32x3::from(0.0).with_w(
                    (wedge_g1[1] * other[e31]) + (wedge_g1[2] * other[e12])
                        - (wedge_g0_xyz[0] * right_anti_dual_g2[0])
                        - (wedge_g0_xyz[1] * right_anti_dual_g2[1])
                        - (wedge_g0_xyz[2] * right_anti_dual_g2[2]),
                ),
            // e1, e2, e3, e4
            (Simd32x4::from([wedge_g1[2], wedge_g1[0], wedge_g1[1], wedge_g0_xyz[1] * other[e42]]) * other.group0().yzx().with_w(1.0))
                + Simd32x3::from(0.0).with_w(wedge_g0_xyz[2] * other[e43])
                + (wedge_g0_xyz * Simd32x3::from(other[e45])).with_w(wedge_g0_xyz[0] * other[e41])
                - (other.group0().zxy() * wedge_g1.yzx()).with_w(0.0),
        )
    }
}
