                - (wedge_g1.zxyx() * right_anti_dual_g1_xyz.yzx().with_w(right_anti_dual_g2_xyz[0]))
                - (wedge_g1.wwwy() * other.group0().with_w(right_anti_dual_g2_xyz[1]))
